#include "unity.h"
#include "helpers.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void setUp(void) { }
void tearDown(void) { }

void unit_test_get_number_success_valid_digits(void) {
    // Setup: Create a temporary file with a valid decimal number
    const char *lines[] = {"12345"};
    char *filename = helper_create_test_file(lines, 1);
    TEST_ASSERT_NOT_NULL(filename);

    FILE *fp = fopen(filename, "r");
    TEST_ASSERT_NOT_NULL(fp);

    // Buffer large enough for the line
    char buffer[100];
    // Output array for digits
    uint8_t out_int[100] = {0};

    // Test: Call get_number - this should succeed and return 0
    int result = get_number(fp, buffer, out_int);
    TEST_ASSERT_EQUAL_INT(0, result);

    // Assertions: Verify the digits are stored correctly in little-endian order
    // Input "12345" -> out_int[0] = 5, out_int[1] = 4, out_int[2] = 3, out_int[3] = 2, out_int[4] = 1
    TEST_ASSERT_EQUAL_UINT8(5, out_int[0]);
    TEST_ASSERT_EQUAL_UINT8(4, out_int[1]);
    TEST_ASSERT_EQUAL_UINT8(3, out_int[2]);
    TEST_ASSERT_EQUAL_UINT8(2, out_int[3]);
    TEST_ASSERT_EQUAL_UINT8(1, out_int[4]);

    // Cleanup
    fclose(fp);
    helper_cleanup_test_file(filename);
    free(filename);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_get_number_success_valid_digits);
    return UNITY_END();
}
